// Read the number of unique characters in the dictionary
int num_chars;
infile.read(reinterpret_cast<char*>(&num_chars), sizeof(int));

// Create a temporary root node
std::shared_ptr<Node> current = root;

// Read each character and its Huffman code
for (int i = 0; i < num_chars; ++i) {
    unsigned char ch;
    infile.read(reinterpret_cast<char*>(&ch), sizeof(unsigned char));

    // Reset to root for each character
    current = root;

    // Read the bits of the Huffman code
    char byte;
    int bit_pos = 0;
    bool done = false;

    while (!done) {
        infile.read(&byte, sizeof(char));
        for (int j = 0; j < 8; ++j) {
            if (bit_pos >= 8) {
                bit_pos = 0;
                break;
            }

            bool bit = (byte >> (7 - j)) & 1;
            if (bit) {
                if (!current->right) {
                    current->right = std::make_shared<Node>('+', 0);
                }
                current = current->right;
            } else {
                if (!current->left) {
                    current->left = std::make_shared<Node>('+', 0);
                }
                current = current->left;
            }

            bit_pos++;
            if (bit_pos == 8) {
                done = true;
                break;
            }
        }
    }

    // Set the character at the leaf node
    current->character = ch;
    current->frequency = 1; // Frequency doesn't matter for decompression
}

